json.task_info.json:
{
  "paper_id": "paper_3c058fa17fa7c54e",
  "task_type": "autonomous_research",
  "title": "Autonomous investigation of S1/T1 energetics for anthracene sigma-bond emitters",
  "category": "excited_state_spectroscopy_photochemistry",
  "difficulty": "hard",
  "difficulty_reasons": [
    "Two very large, highly substituted molecules require conformer generation and geometry optimization.",
    "Lowest singlet and triplet identification requires excited-state root/state validation and spin checks.",
    "Two-system coverage plus sensitivity analysis and auditable bounded-failure handling create a substantial exploration and validation space."
  ],
  "paper": {
    "title": "σ-Bond unit strategy: Constructing deep-blue triplet-triplet annihilation emitters based on anthracene core for efficient non-doped OLEDs",
    "doi": "10.1016/j.dyepig.2025.113436",
    "journal": "Dyes and Pigments",
    "publication_date": "2026-03-15"
  },
  "data": [
    {
      "path": "data/inputs",
      "description": "Public systematic molecular names, formulas, charge and multiplicity."
    }
  ],
  "required_deliverables": [
    {
      "path": "report/results.json",
      "description": "Validated per-system S1/T1 energies, derived inequalities, conclusion and limitations."
    }
  ]
}

json.evaluation/scoring_rules.json:
{
  "paper_id": "paper_3c058fa17fa7c54e",
  "rules": [
    {
      "rule_id": "r_geometry",
      "reference_id": "kp_geometry",
      "type": "semantic",
      "expected": "Auditable geometry identity, convergence and stationary point evidence for both named systems.",
      "binding": {
        "artifact_paths": [
          "report/results.json"
        ],
        "fields": [
          "$.systems[*].geometry",
          "$.systems[*].validation"
        ],
        "comparison": "expert process validation"
      }
    },
    {
      "rule_id": "r_states",
      "reference_id": "kp_states",
      "type": "semantic",
      "expected": "Explicit lowest-state assignment and provenance for both systems.",
      "binding": {
        "artifact_paths": [
          "report/results.json"
        ],
        "fields": [
          "$.systems[*].validation"
        ],
        "comparison": "expert process validation"
      }
    },
    {
      "rule_id": "r_energies",
      "reference_id": "kp_energies",
      "type": "semantic",
      "binding": {
        "artifact_paths": [
          "report/results.json"
        ],
        "fields": [
          "$.systems[*]"
        ],
        "comparison": "expert scientific comparison of explicit lowest-state energies and signed gaps against Figure 2"
      },
      "expected": "For both systems, assess the explicit lowest singlet and triplet energies and signed gaps under the public vertical-energy convention. Use the spin-labelled values in main Figure 2, not the reversed An-sigma-Ph prose pair. Establish method/state comparability from raw outputs; do not automatically reorder states by numerical magnitude. A truthful bounded failure is a diagnostic record, not a substitute for an unavailable scientific energy result."
    },
    {
      "rule_id": "r_final",
      "reference_id": "c_final",
      "type": "semantic",
      "expected": "The required S1 and T1 energies in eV support explicit per-system evaluation of both TTA energetic conditions, 2*T1>S1 and S1-T1>0.5 eV.",
      "binding": {
        "artifact_paths": [
          "report/results.json"
        ],
        "fields": [
          "$.systems[*].inequality_assessment",
          "$.conclusion",
          "$.sensitivity",
          "$.coverage"
        ],
        "comparison": "expert semantic comparison"
      }
    }
  ],
  "scoring_policy": "dual_axis_100.scientific_results.v1"
}

